const d=["border-red-600","focus:ring-red-600","focus:border-red-600","focus:text-red-600","dark:border-red-600","dark:focus:ring-red-600","dark:focus:border-red-600","dark:focus:text-red-600"];function n(t){t.classList.remove(...d);const e=t.id?.trim();if(e){const r=document.getElementById(`${e}_error`);if(r){r.remove();return}}const o=t.name?.trim();if(o){const r=document.getElementById(`${o}_error`);r&&r.remove()}}document.addEventListener("DOMContentLoaded",()=>{document.querySelectorAll("input, select, textarea").forEach(e=>{e.addEventListener("input",()=>n(e))})});
